import re, os, collections

def strip_comments(s):
    out=[]; i=0; depth=0
    while i < len(s):
        if depth==0 and s.startswith('/-',i):
            depth=1; i+=2; continue
        if depth>0:
            if s.startswith('/-',i): depth+=1; i+=2; continue
            if s.startswith('-/',i):
                depth-=1; i+=2
                continue
            out.append(' ' if s[i]!='\n' else '\n'); i+=1; continue
        if s.startswith('--',i):
            j=s.find('\n',i)
            if j<0: j=len(s)
            out.append(' '*(j-i)); i=j; continue
        out.append(s[i]); i+=1
    return ''.join(out)

DECL=re.compile(r'^(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+|nonrec\s+|partial\s+|unsafe\s+|scoped\s+)*(theorem|lemma|def|instance|abbrev|structure|class|example)\b')

files=collections.Counter(); files_et=collections.Counter()
hits=[]; hits_et=[]
for root,ds,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f)
        raw=open(p).read()
        src=strip_comments(raw)
        lines=src.split('\n')
        rawlines=raw.split('\n')
        # split into top-level decl blocks: a line starting at col 0 with decl keyword
        starts=[]
        for i,l in enumerate(lines):
            if l and not l[0].isspace() and DECL.match(l):
                starts.append(i)
        starts.append(len(lines))
        for a,b in zip(starts,starts[1:]):
            block='\n'.join(lines[a:b])
            # signature = up to first := or 'where' at any depth (approximation, same as stated method)
            m=re.search(r':=|\bwhere\b', block)
            sig=block[:m.start()] if m else block
            name=re.match(r'^\S+\s+(\S+)', lines[a])
            nm=name.group(1) if name else '?'
            # bracketed binders
            brs=re.findall(r'\[[^\[\]]*\]', sig)
            et=any('HasPicSchemeEt' in x for x in brs)
            sh=any(re.search(r'HasPicScheme(?!Et)', x) for x in brs)
            if et:
                files_et[f]+=1; hits_et.append((f,a+1,nm))
            elif sh:
                files[f]+=1; hits.append((f,a+1,nm))
print("HasPicScheme total:", sum(files.values()))
for k,v in files.most_common(): print("  ",k,v)
print("HasPicSchemeEt total:", sum(files_et.values()))
for k,v in files_et.most_common(): print("  ",k,v)
print("--- Jacobian.lean HasPicScheme hits ---")
for h in hits:
    if h[0]=='Jacobian.lean': print(h)
print("--- Jacobian.lean Et hits ---")
for h in hits_et:
    if h[0]=='Jacobian.lean': print(h)
EOF
